'use client'

// TEMPORARY debug harness — delete after verifying.
import { RichTextEditor } from '@mantine/tiptap'
import Placeholder from '@tiptap/extension-placeholder'
import TextAlign from '@tiptap/extension-text-align'
import StarterKit from '@tiptap/starter-kit'
import { useEditor } from '@tiptap/react'
import { useState } from 'react'
import TextEditIcon from '@/components/icons/TextEditIcon'
import EmojiPicker from '@/components/feed/post/EmojiPicker'

export default function AlignTest() {
  const [formattingOpen, setFormattingOpen] = useState(false)
  const editor = useEditor({
    immediatelyRender: false,
    extensions: [
      StarterKit.configure({ heading: false, blockquote: false, code: false, codeBlock: false, horizontalRule: false, strike: false }),
      TextAlign.configure({ types: ['paragraph'] }),
      Placeholder.configure({ placeholder: 'test' }),
    ],
    content: '<p>السلام عليكم ورحمة الله وبركاته</p>',
  })

  return (
    <div style={{ padding: 24 }}>
      <RichTextEditor editor={editor} id="test-editor" className="overflow-hidden rounded-md border bg-white shadow-none border-[#E5EAF2]">
        {formattingOpen && (
          <RichTextEditor.Toolbar sticky={false} className="border-b border-[#E5EAF2] bg-[#F8FAFD] px-1 py-1">
            <RichTextEditor.ControlsGroup>
              <RichTextEditor.Bold />
              <RichTextEditor.Italic />
            </RichTextEditor.ControlsGroup>
            <RichTextEditor.ControlsGroup>
              <RichTextEditor.AlignLeft />
              <RichTextEditor.AlignCenter />
              <RichTextEditor.AlignRight />
            </RichTextEditor.ControlsGroup>
            <EmojiPicker label="Insert emoji" onSelect={(e) => editor?.chain().focus().insertContent(e).run()} />
          </RichTextEditor.Toolbar>
        )}
        <RichTextEditor.Content id="test-content" className="bg-white px-3 py-2.5 text-[15px] [&_.ProseMirror]:min-h-[120px]" />
        <div className="flex items-center bg-white px-1.5 pb-1.5">
          <button
            id="fmt-toggle"
            type="button"
            onClick={() => setFormattingOpen((c) => !c)}
            aria-label="Formatting options"
            aria-expanded={formattingOpen}
            className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-md ${
              formattingOpen ? 'bg-[#EDF3FC] text-[#1D74E0]' : 'text-[#5A6B84] hover:bg-[#F3F6FB]'
            }`}
          >
            <TextEditIcon className="h-4 w-4" />
          </button>
        </div>
      </RichTextEditor>
    </div>
  )
}
